// Generates the effect documentation from each effect's definition:
//   docs/effects/<id>.md                  one page per effect
//   docs/effects/index.md                 the catalogue, grouped by family
//   docs/.vitepress/effects.json          the sidebar
//   docs/.vitepress/theme/effect-registry.ts  lazy loaders for <EffectDemo>
// Hand-written notes in src/effects/<id>/notes.md are appended to the page.
// With --check, fails when any generated file is stale or an extra page exists.
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import * as prettier from 'prettier';
import { loadEffects, loadSource, packageRoot, repoRoot } from './lib.mjs';

const check = process.argv.includes('--check');
const effects = await loadEffects();
const { effectFamilies } = await loadSource('src/effect/index.ts');
const { entries } = JSON.parse(
  readFileSync(`${packageRoot}credits.json`, 'utf8'),
);
const credits = new Map(entries.map((entry) => [entry.id, entry]));
const budgets = JSON.parse(
  readFileSync(`${packageRoot}size-budgets.json`, 'utf8'),
);
const byName = new Map(
  effects.map(({ id, factory }) => [id, factory.definition]),
);
function camel(id) {
  return id.replace(/-(\w)/g, (_, c) => c.toUpperCase());
}
const escape = (text) => String(text).replace(/\|/g, '\\|');

function formatValue(param, value) {
  switch (param.kind) {
    case 'texture':
      return value === null ? 'null' : `'${value}'`;
    case 'vec2':
    case 'vec3':
      return `[${value.join(', ')}]`;
    case 'color':
    case 'select':
      return `'${value}'`;
    default:
      return String(value);
  }
}

function typeOf(param) {
  switch (param.kind) {
    case 'select':
      return param.options.map((o) => `'${o}'`).join(' \\| ');
    case 'color':
      return 'hex color';
    case 'texture':
      return `${param.dimension.toUpperCase()} texture${
        param.samples
          ? ` or ${Object.keys(param.samples)
              .map((n) => `'${n}'`)
              .join(' \\| ')}`
          : ''
      }`;
    case 'vec2':
      return '[x, y]';
    case 'vec3':
      return '[x, y, z]';
    default:
      return param.kind === 'bool'
        ? 'boolean'
        : param.kind === 'int'
          ? 'integer'
          : 'number';
  }
}

function range(param) {
  if (!('min' in param)) return '';
  return `${param.min} – ${param.max}${param.unit ? ` ${param.unit}` : ''}`;
}

function page(factory) {
  const { definition } = factory;
  const { name, meta, params } = definition;
  const factoryName = camel(name);
  const credit = credits.get(`effects/${name}`);
  const notesFile = `${packageRoot}src/effects/${name}/notes.md`;
  const notes = existsSync(notesFile)
    ? readFileSync(notesFile, 'utf8').trim()
    : '';
  const exampleParams = Object.entries(definition.presets ?? {})[0];
  const motion = definition.motion ?? 'static';
  const lines = [
    '---',
    `title: ${meta.title}`,
    `description: ${JSON.stringify(meta.description)}`,
    'outline: [2, 3]',
    '---',
    '',
    `<!-- Generated by packages/xtree/scripts/effect-docs.mjs from src/effects/${name}. Do not edit; run \`pnpm effects:docs\`. -->`,
    '',
    `# ${meta.title}`,
    '',
    meta.description,
    '',
    `<EffectDemo effect="${name}" />`,
    '',
    '## Usage',
    '',
    '```ts',
    "import { EffectComposer } from '@mk7s/xtree/core';",
    `import { ${factoryName} } from '@mk7s/xtree/effects/${name}';`,
    '',
    'const composer = new EffectComposer(renderer);',
    'composer.setScene(scene, camera);',
    meta.demo?.selection
      ? `const hero = scene.getObjectByName('hero'); // the objects to select\ncomposer.add(${factoryName}({ mask: { selection: [hero] } }));`
      : exampleParams
        ? `composer.add(${factoryName}({ preset: '${exampleParams[0]}' }));`
        : `composer.add(${factoryName}());`,
    'renderer.setAnimationLoop(() => composer.render());',
    '```',
    '',
    `Every parameter is also a property: \`effect.${Object.keys(params)[0]} = ${formatValue(Object.values(params)[0], Object.values(params)[0].default)}\`. Uniform changes take effect on the next frame without recompiling${Object.values(params).some((p) => p.structural) ? '; parameters marked *structural* recompile the pass that contains the effect' : ''}.`,
    '',
    '## Parameters',
    '',
    '| Parameter | Type | Default | Range | Description |',
    '| --- | --- | --- | --- | --- |',
    ...Object.entries(params).map(
      ([key, param]) =>
        `| \`${key}\`${param.structural ? ' *(structural)*' : ''} | ${typeOf(param)} | \`${escape(formatValue(param, param.default))}\` | ${range(param)} | ${escape(param.description)} |`,
    ),
    '',
    'Every effect also has `blend` (any of the 26 [blend modes](/reference/shaders#modes)), `opacity` (0–1) and `enabled`.',
    '',
  ];
  if (definition.presets && Object.keys(definition.presets).length) {
    lines.push('## Presets', '', '| Preset | Settings |', '| --- | --- |');
    for (const [preset, values] of Object.entries(definition.presets)) {
      const settings = Object.entries(values)
        .map(
          ([key, value]) =>
            `\`${key}: ${escape(formatValue(params[key], value))}\``,
        )
        .join(', ');
      lines.push(`| \`${preset}\` | ${settings} |`);
    }
    lines.push(
      '',
      `Apply one with \`${factoryName}({ preset: 'name' })\` or \`effect.applyPreset('name')\`; presets start from the defaults.`,
      '',
    );
  }
  const sampling = definition.sampling ?? 'pixel';
  const motionText =
    motion === 'static'
      ? 'Static: nothing animates.'
      : motion === 'freeze'
        ? 'Freezes: when motion is off (reduced motion, high contrast or `composer.motion = false`) the effect holds its current frame.'
        : `Settles: when motion is off it switches to still values (${Object.entries(
            motion.settle,
          )
            .map(([k, v]) => `\`${k}: ${formatValue(params[k], v)}\``)
            .join(', ')}) without changing your settings.`;
  const bufferNames = { depth: 'depth', normal: 'normals' };
  const defaultBuffers = factory().requiredBuffers();
  const buffersText =
    typeof definition.buffers === 'function'
      ? `depend on its settings; with the defaults it reads ${defaultBuffers.map((b) => bufferNames[b]).join(' and ') || 'none'}.`
      : defaultBuffers.length
        ? `reads ${defaultBuffers.map((b) => bufferNames[b]).join(' and ')}, which the composer renders only while an effect needs them.`
        : null;
  const maskText =
    (definition.masking ?? 'opacity') === 'custom'
      ? 'reads its `mask` itself rather than fading by it (see the description); any [mask kind](/guide/masks) works.'
      : 'set `effect.mask` to a texture, depth range or selection to limit where it applies; see [masks](/guide/masks).';
  lines.push(
    '## Details',
    '',
    `- **Family:** ${effectFamilies[meta.family]} · tracked as story ${meta.story} in the [plan](https://github.com/s4njee/xtree/blob/main/plan.md).`,
    `- **Passes:** ${
      sampling === 'pixel'
        ? 'reads only its own pixel, so it merges into the pass before it.'
        : 'samples the pass input at other positions, so it starts a new merged pass; following pixel effects join that pass.'
    }${definition.setup ? ' It also renders its own intermediate passes before the merged pass.' : ''}`,
    ...(buffersText ? [`- **Geometry buffers:** ${buffersText}`] : []),
    `- **Masks:** ${maskText}`,
    `- **Motion:** ${motionText}`,
    `- **Size:** ${(budgets[`./effects/${name}`] / 1024).toFixed(1)} KB gzip budget for \`@mk7s/xtree/effects/${name}\`, including the shared effect runtime.`,
    '',
  );
  if (notes) lines.push(notes, '');
  if (credit) {
    const licence =
      credit.kind === 'original'
        ? 'Original implementation (MIT).'
        : `${credit.kind === 'ported' ? 'Ported' : 'Derived'} from ${credit.notice} (${credit.licence}); see THIRD_PARTY_NOTICES.md.`;
    lines.push(
      '## Credits',
      '',
      `${licence} References: ${credit.references.join('; ')}.`,
      '',
    );
  }
  const related = (meta.related ?? []).filter((id) => byName.has(id));
  if (related.length) {
    lines.push(
      '## Related',
      '',
      ...related.map(
        (id) =>
          `- [${byName.get(id).meta.title}](./${id}) — ${byName.get(id).meta.description.split('. ')[0].replace(/\.$/, '')}.`,
      ),
      '',
    );
  }
  return lines.join('\n');
}

const families = Object.entries(effectFamilies)
  .map(([family, title]) => ({
    family,
    title,
    effects: effects.filter(
      ({ factory }) => factory.definition.meta.family === family,
    ),
  }))
  .filter((group) => group.effects.length);

const index = [
  '---',
  'title: Effects',
  '---',
  '',
  '<!-- Generated by packages/xtree/scripts/effect-docs.mjs. Do not edit; run `pnpm effects:docs`. -->',
  '',
  '# Effects',
  '',
  `${effects.length} effects so far, out of the 141 planned. Each page has a live demo you can adjust, compare and copy.`,
  '',
  ...families.flatMap(({ title, effects: group }) => [
    `## ${title}`,
    '',
    '<div class="xt-effect-grid">',
    ...group.map(({ id, factory }) => {
      const { meta } = factory.definition;
      return `<a class="hcss-card xt-effect-card" href="./${id}"><strong>${meta.title}</strong><span>${meta.description.split('. ')[0].replace(/\.$/, '')}.</span></a>`;
    }),
    '</div>',
    '',
  ]),
].join('\n');

const sidebar = families.map(({ title, effects: group }) => ({
  text: title,
  items: group.map(({ id, factory }) => ({
    text: factory.definition.meta.title,
    link: `/effects/${id}`,
  })),
}));

const registry = [
  '// Generated by packages/xtree/scripts/effect-docs.mjs. Do not edit; run `pnpm effects:docs`.',
  "import type { Effect, EffectFactory, ParamSchema } from '@mk7s/xtree/effect';",
  '',
  '/** Loads an effect factory by id, so each docs page only downloads its own effect. */',
  'export const effectLoaders: Record<string, () => Promise<EffectFactory<ParamSchema>>> = {',
  ...effects.map(
    ({ id }) =>
      `  '${id}': () => import('@mk7s/xtree/effects/${id}').then((m) => m.${camel(id)} as unknown as EffectFactory<ParamSchema>),`,
  ),
  '};',
  '',
  'export type { Effect };',
  '',
].join('\n');

const outputs = new Map([
  ...effects.map(({ factory }) => [
    `${repoRoot}docs/effects/${factory.definition.name}.md`,
    page(factory),
  ]),
  [`${repoRoot}docs/effects/index.md`, index],
  [
    `${repoRoot}docs/.vitepress/effects.json`,
    `${JSON.stringify(sidebar, null, 2)}\n`,
  ],
  [`${repoRoot}docs/.vitepress/theme/effect-registry.ts`, registry],
]);

const stale = [];
for (const [file, raw] of outputs) {
  const config = (await prettier.resolveConfig(file)) ?? {};
  const content = await prettier.format(raw, { ...config, filepath: file });
  const current = existsSync(file) ? readFileSync(file, 'utf8') : '';
  if (current === content) continue;
  if (check) stale.push(file.replace(repoRoot, ''));
  else writeFileSync(file, content);
}
const expected = new Set([...effects.map(({ id }) => `${id}.md`), 'index.md']);
const extra = readdirSync(`${repoRoot}docs/effects`).filter(
  (f) => f.endsWith('.md') && !expected.has(f),
);
if (check) {
  if (stale.length || extra.length) {
    console.error(
      [
        ...stale.map((f) => `${f} is out of date; run \`pnpm effects:docs\`.`),
        ...extra.map((f) => `docs/effects/${f} has no effect.`),
      ].join('\n'),
    );
    process.exit(1);
  }
  console.log(`Effect docs are up to date (${effects.length} effects).`);
} else {
  if (extra.length) console.warn(`No effect for: ${extra.join(', ')}`);
  console.log(`Wrote docs for ${effects.length} effects.`);
}
